-- MP-0054: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0054: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0054: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='warisan' and type='party') then raise exception 'MP-0054: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('vivian-wong-shir-yee','mohd-kurniawan-naim-moktar','mohammad-yusof-apdal') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0054: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('sandakan','kinabatangan','lahad datu') and slug not in ('vivian-wong-shir-yee','mohd-kurniawan-naim-moktar','mohammad-yusof-apdal')) then raise exception 'MP-0054: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0054:%' and (m.source_type <> 'editorial' or e.slug not in ('vivian-wong-shir-yee','mohd-kurniawan-naim-moktar','mohammad-yusof-apdal') or m.import_key not like 'MP-0054:' || e.slug || ':%')) then raise exception 'MP-0054: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'vivian-wong-shir-yee','Vivian Wong Shir Yee','government','Member of the Dewan Rakyat','Sandakan','Sabah','Vivian Wong Shir Yee represents Sandakan, Sabah, in the Dewan Rakyat. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4225','/portraits/vivian-wong-shir-yee.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P186.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4225"}, {"label": "DAP · current Sabah representatives", "url": "https://dapmalaysia.org/en/sabah-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-kurniawan-naim-moktar','Mohd Kurniawan Naim Moktar','government','Member of the Dewan Rakyat','Kinabatangan','Sabah','Mohd Kurniawan Naim Moktar represents Kinabatangan, Sabah, in the Dewan Rakyat. Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4226','/portraits/mohd-kurniawan-naim-moktar.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/yb%20naim.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4226"}, {"label": "UMNO · Kinabatangan youth chief and campaign commitments, 11 January 2026", "url": "https://umno-online.my/2026/01/11/prk-kinabatangan-naim-tumpu-usaha-perkasa-belia-pembangunan-pulau-tanjung-aru/"}, {"label": "Parliamentary oath · 27 January 2026", "url": "https://umno-online.my/2026/01/27/mohd-kurniawan-naim-angkat-sumpah-ahli-dewan-rakyat/"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohammad-yusof-apdal','Mohammad Yusof Apdal','government','Deputy Minister of Science, Technology and Innovation','Lahad Datu','Sabah','Mohammad Yusof Apdal represents Lahad Datu, Sabah, in the Dewan Rakyat. Current role: Deputy Minister of Science, Technology and Innovation. Affiliated with WARISAN.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4227','/portraits/mohammad-yusof-apdal.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P188.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4227"}, {"label": "WARISAN · current federal-government support, 3 August 2026", "url": "https://www.bernama.com/en/news.php?id=2589775"}]'::jsonb from public.entities parent where parent.slug='warisan' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('vivian-wong-shir-yee','mohd-kurniawan-naim-moktar','mohammad-yusof-apdal') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0054: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0054:mohd-kurniawan-naim-moktar:pulau-tanjung-aru-youth-enterprise','Develop youth enterprise opportunities in Pulau Tanjung Aru','Economy',null,null,null,'2026-01-11','https://umno-online.my/2026/01/11/prk-kinabatangan-naim-tumpu-usaha-perkasa-belia-pembangunan-pulau-tanjung-aru/',null,null,'During the by-election campaign, Kurniawan pledged to prioritise youth jobs and work with KUSKOP on skills, microfinance and business guidance if elected.','He subsequently became the Kinabatangan MP. This pass did not verify a matching programme launch, financing disbursement, employment count or completion deadline.','2026-11-10','editorial',false from public.entities e where e.slug='mohd-kurniawan-naim-moktar' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0054:mohd-kurniawan-naim-moktar:pulau-tanjung-aru-community-facilities','Prioritise renewal of Pulau Tanjung Aru community facilities','Infrastructure',null,null,null,'2026-01-11','https://umno-online.my/2026/01/11/prk-kinabatangan-naim-tumpu-usaha-perkasa-belia-pembangunan-pulau-tanjung-aru/',null,null,'Kurniawan’s campaign statement committed attention to ageing infrastructure and proposed new mosque, hall and sports facilities, including futsal and volleyball spaces.','A campaign undertaking, conditional on election at the time. Project approvals, budgets, construction and completed facilities were not verified after he took office; no invented deadline or percentage is assigned.','2026-11-10','editorial',false from public.entities e where e.slug='mohd-kurniawan-naim-moktar' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0054:mohammad-yusof-apdal:mimos-technology-readiness-2026','Advance 22 MIMOS technology releases toward readiness assessment','Economy','in_progress',null,'2026-12-31',null,null,'2026-09-30','https://www.bernama.com/en/news.php?id=2613340','The report from the MIMOS technology preview describes another 22 technology-release packages progressing toward Technology Readiness Assessment by the end of 2026, in the deputy minister’s ministry portfolio.','A reported agency pipeline, not the deputy minister’s sole delivery. The source was published 30 September with a 29 September dateline. Its 17 licensed packages, 29 ready releases and 22 in assessment are different cohorts, so no percentage is inferred. The year-only schedule uses 31 December as a display marker.','2026-11-10','editorial',false from public.entities e where e.slug='mohammad-yusof-apdal' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

